//! The Mapping `convert_to` finds between two SkyFrames, checked against the
//! C library for every pair of celestial coordinate systems.
//!
//! `sky_convert_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/sky_convert_probe.c`, which calls `astConvert`
//! between SkyFrames that differ in Epoch, Equinox and observer position,
//! with the destination Frame's AlignSystem unset and set to each system
//! that changes which conversion steps `MakeSkyMapping` (skyframe.c:5956)
//! includes, and transforms three points with the result.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "sky_convert_oracle/cases.rs"]
mod cases;

use ast_core::frames::{Frame, FrameRef, SkyFrame, SkySystem};

/// Cases whose AZEL result may differ from C in the last few bits.
///
/// The final E2H step (slamap.c:298 `De2h`, ported as `de2h_with_aberration`)
/// takes `sin` and `cos` of the same angles. Apple clang merges each pair into
/// one `__sincos_stret` call when it builds the C library, and that call can
/// round differently from separate `sin` and `cos`. A release build of this
/// crate makes the same merge and reproduces C exactly; an unoptimised test
/// build does not. The steps before E2H agree bit for bit. One unit in the
/// last place of an intermediate becomes up to five in the elevation, which
/// `atan2` takes from a small `z`; each case records the bound measured for it.
///
/// Fields: configuration, from System, to System, to AlignSystem, maximum
/// difference in units in the last place, reason.
type SincosLicence = (
    usize,
    &'static str,
    &'static str,
    Option<&'static str>,
    u64,
    &'static str,
);

const SINCOS_MERGE_LICENSED: &[SincosLicence] = &[
    (
        0,
        "AZEL",
        "AZEL",
        Some("FK4"),
        5,
        "E2H elevation, sincos merge",
    ),
    (
        0,
        "AZEL",
        "AZEL",
        Some("FK4-NO-E"),
        5,
        "E2H elevation, sincos merge",
    ),
    (
        0,
        "ICRS",
        "AZEL",
        Some("GAPPT"),
        1,
        "E2H azimuth, sincos merge",
    ),
];

/// The licensed difference in units in the last place for a case, if any.
fn sincos_licence(config: usize, from: &str, to: &str, align: Option<&str>) -> Option<u64> {
    SINCOS_MERGE_LICENSED
        .iter()
        .find(|&&(c, f, t, a, _, _)| c == config && f == from && t == to && a == align)
        .map(|&(.., ulps, _)| ulps)
}

/// Whether two values are at most `ulps` units in the last place apart.
fn within_ulps(a: f64, b: f64, ulps: u64) -> bool {
    a == b || (a.signum() == b.signum() && a.to_bits().abs_diff(b.to_bits()) <= ulps)
}

fn convert(
    config: usize,
    from_sys: &str,
    to_sys: &str,
    align: Option<&str>,
) -> Option<Vec<[f64; 2]>> {
    let from = sky(from_sys, cases::FROM_PROPS[config]);
    let mut to = sky(to_sys, cases::TO_PROPS[config]);
    if let Some(a) = align {
        to.set_align_system(SkySystem::parse(a).expect("known system"));
    }
    let fs = from.convert_to(&to, &[]).unwrap()?;
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    let xin: Vec<f64> = cases::POINTS.iter().map(|p| p[0]).collect();
    let yin: Vec<f64> = cases::POINTS.iter().map(|p| p[1]).collect();
    let (xout, yout) = map.tran2(&xin, &yin, true).unwrap();
    Some(xout.iter().zip(&yout).map(|(&x, &y)| [x, y]).collect())
}

fn sky(system: &str, props: [f64; 4]) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    f.set_system(SkySystem::parse(system).expect("known system"));
    f.set_epoch_mjd(props[0]);
    f.set_equinox_mjd(props[1]);
    f.set_obs_lat(props[2]);
    f.set_obs_lon(props[3]);
    f
}

#[test]
fn convert_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(config, from_sys, to_sys, align, expected) in cases::CASES {
        let label = format!("config {config} {from_sys} -> {to_sys} align {align:?}");
        let got = convert(config, from_sys, to_sys, align);
        match (got, expected) {
            (None, None) => {}
            (Some(_), None) => failures.push(format!("{label}: converts, C finds no conversion")),
            (None, Some(_)) => failures.push(format!("{label}: no conversion, C converts")),
            (Some(got), Some(want)) => {
                let same = match sincos_licence(config, from_sys, to_sys, align) {
                    Some(ulps) => got.iter().zip(&want).all(|(g, w)| {
                        (within_ulps(g[0], w[0], ulps) && within_ulps(g[1], w[1], ulps))
                            || crate::common::c_values_eq(g, w)
                    }),
                    None => crate::common::c_values_eq(got.as_flattened(), want.as_flattened()),
                };
                if !same {
                    failures.push(format!("{label}: got {got:?}, C gives {want:?}"));
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}

/// Each licensed case still needs its licence in an unoptimised build, and
/// matches C exactly in an optimised one; a case that stops differing in the
/// unoptimised build must be removed from `SINCOS_MERGE_LICENSED`.
#[test]
fn sincos_licences_are_still_needed() {
    for &(config, from_sys, to_sys, align, _, reason) in SINCOS_MERGE_LICENSED {
        let want = cases::CASES
            .iter()
            .find(|c| c.0 == config && c.1 == from_sys && c.2 == to_sys && c.3 == align)
            .and_then(|c| c.4)
            .expect("licensed case is in the corpus and converts");
        let got = convert(config, from_sys, to_sys, align).expect("converts");
        let exact = got == want;
        assert_eq!(
            exact,
            !cfg!(debug_assertions),
            "config {config} {from_sys} -> {to_sys} align {align:?} ({reason}): exact match is {exact}"
        );
    }
}
